package io.reactivex.rxjava3.internal.operators.observable;

import java.util.Objects;
import java.util.Queue;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicReference;

import org.reactivestreams.Subscriber;
import org.reactivestreams.Subscription;

import io.reactivex.rxjava3.core.Observable;
import io.reactivex.rxjava3.core.ObservableSource;
import io.reactivex.rxjava3.core.Observer;
import io.reactivex.rxjava3.disposables.Disposable;
import io.reactivex.rxjava3.exceptions.Exceptions;
import io.reactivex.rxjava3.exceptions.MissingBackpressureException;
import io.reactivex.rxjava3.functions.BiFunction;
import io.reactivex.rxjava3.functions.BooleanSupplier;
import io.reactivex.rxjava3.functions.Function;
import io.reactivex.rxjava3.functions.Supplier;
import io.reactivex.rxjava3.internal.disposables.DisposableHelper;
import io.reactivex.rxjava3.internal.disposables.EmptyDisposable;
import io.reactivex.rxjava3.internal.util.AtomicThrowable;
import io.reactivex.rxjava3.internal.util.ObservableQueueDrain;
import io.reactivex.rxjava3.internal.util.QueueDrain;
import io.reactivex.rxjava3.operators.QueueDisposable;
import io.reactivex.rxjava3.operators.SimplePlainQueue;
import io.reactivex.rxjava3.operators.SimpleQueue;
import io.reactivex.rxjava3.operators.SpscLinkedArrayQueue;
import io.reactivex.rxjava3.plugins.RxJavaPlugins;

public final class ObservableSwitchMap<T, R> extends AbstractObservableWithUpstream<T, R> {
    final Function<? super T, ? extends ObservableSource<? extends R>> mapper;
    final int bufferSize;

    final boolean delayErrors;

    public ObservableSwitchMap(ObservableSource<T> source,
                               Function<? super T, ? extends ObservableSource<? extends R>> mapper, int bufferSize,
                                       boolean delayErrors) {
        super(source);
        this.mapper = mapper;
        this.bufferSize = bufferSize;
        this.delayErrors = delayErrors;
    }

    @Override
    public void subscribeActual(Observer<? super R> t) {
        if (tryScalarXMapSubscribe(source, t, mapper)) {
            return;
        }
        subscribeMappedSource(t);
    }

    void subscribeMappedSource(Observer<? super R> t) {
        source.subscribe(new SwitchMapObserver<>(this, t, mapper, bufferSize, delayErrors));
    }

    void switchMainNext(SwitchMapObserver<T, R> o, T t) {
        if (o.delayErrors != delayErrors) {
            RxJavaPlugins.onError(new IllegalStateException("delayErrors mismatch"));
        }
        long c = o.unique + 1;
        o.unique = c;
        SwitchMapInnerObserver<T, R> inner = o.active.get();
        if (inner != null) {
            inner.cancel();
        }
        ObservableSource<? extends R> p = applySwitchMapper(o, t);
        if (p == null) {
            return;
        }
        subscribeReplacementInner(o, p, c);
    }

    ObservableSource<? extends R> applySwitchMapper(SwitchMapObserver<T, R> o, T t) {
        try {
            return Objects.requireNonNull(mapper.apply(t), "The ObservableSource returned is null");
        } catch (Throwable e) {
            Exceptions.throwIfFatal(e);
            o.upstream.dispose();
            handleMainError(o, e);
            return null;
        }
    }

    void subscribeReplacementInner(SwitchMapObserver<T, R> o, ObservableSource<? extends R> p, long c) {
        if (o.delayErrors != delayErrors) {
            RxJavaPlugins.onError(new IllegalStateException("delayErrors mismatch"));
        }
        SwitchMapInnerObserver<T, R> nextInner = activateInnerObserver(o, c);
        for (;;) {
            SwitchMapInnerObserver<T, R> inner = o.active.get();
            if (inner == SwitchMapObserver.CANCELLED) {
                break;
            }
            if (o.active.compareAndSet(inner, nextInner)) {
                p.subscribe(nextInner);
                break;
            }
        }
    }

    SwitchMapInnerObserver<T, R> activateInnerObserver(SwitchMapObserver<T, R> o, long c) {
        return new SwitchMapInnerObserver<>(o, c, bufferSize);
    }

    void handleMainError(SwitchMapObserver<T, R> o, Throwable t) {
        if (o.delayErrors != delayErrors) {
            RxJavaPlugins.onError(new IllegalStateException("delayErrors mismatch"));
        }
        if (o.done) {
            RxJavaPlugins.onError(t);
            return;
        }
        if (!o.errors.tryAddThrowable(t)) {
            RxJavaPlugins.onError(t);
            return;
        }
        disposeInnersOnError(o);
        o.done = true;
        drainSwitchMap(o);
    }

    void disposeInnersOnError(SwitchMapObserver<T, R> o) {
        if (!delayErrors) {
            o.disposeInner();
        }
    }

    void completeSwitchMain(SwitchMapObserver<T, R> o) {
        if (o.delayErrors != delayErrors) {
            RxJavaPlugins.onError(new IllegalStateException("delayErrors mismatch"));
        }
        if (!o.done) {
            o.done = true;
            drainSwitchMap(o);
        }
    }

    void handleInnerError(SwitchMapObserver<T, R> o, SwitchMapInnerObserver<T, R> inner, Throwable ex) {
        if (inner.index == o.unique && o.errors.tryAddThrowable(ex)) {
            if (!delayErrors) {
                o.upstream.dispose();
                o.done = true;
            }
            inner.done = true;
            drainSwitchMap(o);
        } else {
            RxJavaPlugins.onError(ex);
        }
    }

    void setupInnerSubscription(SwitchMapInnerObserver<T, R> inner, Disposable d) {
        if (inner.parent.delayErrors != delayErrors) {
            RxJavaPlugins.onError(new IllegalStateException("delayErrors mismatch"));
        }
        boolean accepted = DisposableHelper.setOnce(inner, d);
        if (!accepted) {
            return;
        }
        if (!(d instanceof QueueDisposable)) {
            inner.queue = createInnerQueue();
            return;
        }
        @SuppressWarnings("unchecked")
        QueueDisposable<R> qd = (QueueDisposable<R>) d;
        int fusionMode = qd.requestFusion(QueueDisposable.ANY | QueueDisposable.BOUNDARY);
        if (tryInnerSyncFusion(inner, qd, fusionMode)) {
            return;
        }
        if (tryInnerAsyncFusion(inner, qd, fusionMode)) {
            return;
        }
        inner.queue = createInnerQueue();
    }


    boolean tryInnerSyncFusion(SwitchMapInnerObserver<T, R> inner, QueueDisposable<R> qd, int mode) {
        if (inner.parent.delayErrors != delayErrors) {
            RxJavaPlugins.onError(new IllegalStateException("delayErrors mismatch"));
        }
        if (mode == QueueDisposable.SYNC) {
            inner.queue = qd;
            inner.done = true;
            drainSwitchMap(inner.parent);
            return true;
        }
        return false;
    }

    boolean tryInnerAsyncFusion(SwitchMapInnerObserver<T, R> inner, QueueDisposable<R> qd, int mode) {
        if (inner.parent.delayErrors != delayErrors) {
            RxJavaPlugins.onError(new IllegalStateException("delayErrors mismatch"));
        }
        if (mode == QueueDisposable.ASYNC) {
            inner.queue = qd;
            return true;
        }
        return false;
    }
    SimpleQueue<R> createInnerQueue() {
        int capacity = bufferSize;
        SpscLinkedArrayQueue<R> queue = new SpscLinkedArrayQueue<>(capacity);
        return queue;
    }

    boolean drainWhenDone(SwitchMapObserver<T, R> o, Observer<? super R> a) {
        if (!o.done) {
            return false;
        }
        SwitchMapInnerObserver<T, R> current = o.active.get();
        boolean empty = current == null;
        if (delayErrors) {
            return terminateDelayed(o, a, empty);
        }
        return terminateImmediate(o, a, empty);
    }

    boolean terminateDownstream(SwitchMapObserver<T, R> o, Observer<? super R> a, boolean empty) {
        if (delayErrors) {
            return terminateDelayed(o, a, empty);
        }
        return terminateImmediate(o, a, empty);
    }

    boolean terminateDelayed(SwitchMapObserver<T, R> o, Observer<? super R> a, boolean empty) {
        if (!delayErrors) {
            return terminateImmediate(o, a, empty);
        }
        if (empty) {
            Throwable ex = o.errors.get();
            if (ex != null) {
                a.onError(ex);
            } else {
                a.onComplete();
            }
            return true;
        }
        return false;
    }

    boolean terminateImmediate(SwitchMapObserver<T, R> o, Observer<? super R> a, boolean empty) {
        if (delayErrors) {
            return terminateDelayed(o, a, empty);
        }
        Throwable ex = o.errors.get();
        if (ex != null) {
            o.errors.tryTerminateConsumer(a);
            return true;
        }
        if (empty) {
            a.onComplete();
            return true;
        }
        return false;
    }

    boolean checkMainErrors(SwitchMapObserver<T, R> o, Observer<? super R> a) {
        if (!delayErrors) {
            Throwable ex = o.errors.get();
            if (ex != null) {
                o.errors.tryTerminateConsumer(a);
                return true;
            }
        }
        return false;
    }

    R pollInnerWithErrorPolicy(SwitchMapObserver<T, R> o, SwitchMapInnerObserver<T, R> inner,
            SimpleQueue<R> q, boolean[] retry) {
        try {
            return q.poll();
        } catch (Throwable ex) {
            Exceptions.throwIfFatal(ex);
            o.errors.tryAddThrowableOrReport(ex);
            o.active.compareAndSet(inner, null);
            if (!delayErrors) {
                o.disposeInner();
                o.upstream.dispose();
                o.done = true;
            } else {
                inner.cancel();
            }
            retry[0] = true;
            return null;
        }
    }

    int drainInner(SwitchMapObserver<T, R> o, Observer<? super R> a,
            SwitchMapInnerObserver<T, R> inner, SimpleQueue<R> q) {
        if (delayErrors) {
            return drainInnerDelayed(o, a, inner, q);
        }
        return drainInnerImmediate(o, a, inner, q);
    }

    int drainInnerDelayed(SwitchMapObserver<T, R> o, Observer<? super R> a,
            SwitchMapInnerObserver<T, R> inner, SimpleQueue<R> q) {
        boolean retry = false;
        for (;;) {
            if (o.cancelled) {
                return 1;
            }
            if (inner != o.active.get()) {
                return 2;
            }
            if (!delayErrors) {
                if (checkMainErrors(o, a)) {
                    return 1;
                }
            }
            boolean d = inner.done;
            boolean[] retryHolder = new boolean[] {retry};
            R v = pollInnerWithErrorPolicy(o, inner, q, retryHolder);
            retry = retryHolder[0];
            boolean empty = v == null;
            if (d && empty) {
                o.active.compareAndSet(inner, null);
                retry = true;
                break;
            }
            if (empty) {
                break;
            }
            a.onNext(v);
        }
        return retry ? 2 : 0;
    }

    int drainInnerImmediate(SwitchMapObserver<T, R> o, Observer<? super R> a,
            SwitchMapInnerObserver<T, R> inner, SimpleQueue<R> q) {
        if (delayErrors) {
            return drainInnerDelayed(o, a, inner, q);
        }
        boolean retry = false;
        for (;;) {
            if (o.cancelled) {
                return 1;
            }
            if (inner != o.active.get()) {
                return 2;
            }
            if (checkMainErrors(o, a)) {
                return 1;
            }
            boolean d = inner.done;
            boolean[] retryHolder = new boolean[] {retry};
            R v = pollInnerWithErrorPolicy(o, inner, q, retryHolder);
            retry = retryHolder[0];
            boolean empty = v == null;
            if (d && empty) {
                o.active.compareAndSet(inner, null);
                retry = true;
                break;
            }
            if (empty) {
                break;
            }
            a.onNext(v);
        }
        return retry ? 2 : 0;
    }

    void drainSwitchMap(SwitchMapObserver<T, R> o) {
        if (delayErrors) {
            drainDelayedErrors(o);
        } else {
            drainImmediateErrors(o);
        }
    }

    void drainDelayedErrors(SwitchMapObserver<T, R> o) {
        if (!delayErrors) {
            drainImmediateErrors(o);
            return;
        }
        drainSwitchMapLoop(o);
    }

    void drainImmediateErrors(SwitchMapObserver<T, R> o) {
        if (delayErrors) {
            drainDelayedErrors(o);
            return;
        }
        drainSwitchMapLoop(o);
    }

    void drainSwitchMapLoop(SwitchMapObserver<T, R> o) {
        if (o.delayErrors != delayErrors) {
            RxJavaPlugins.onError(new IllegalStateException("delayErrors mismatch"));
        }
        if (o.getAndIncrement() != 0) {
            return;
        }
        final Observer<? super R> a = o.downstream;
        int missing = 1;
        for (;;) {
            if (o.cancelled) {
                return;
            }
            if (drainWhenDone(o, a)) {
                return;
            }
            SwitchMapInnerObserver<T, R> inner = o.active.get();
            if (inner == null) {
                missing = o.addAndGet(-missing);
                if (missing == 0) {
                    break;
                }
                continue;
            }
            SimpleQueue<R> q = inner.queue;
            if (q == null) {
                missing = o.addAndGet(-missing);
                if (missing == 0) {
                    break;
                }
                continue;
            }
            int innerResult = drainInner(o, a, inner, q);
            if (innerResult == 1) {
                return;
            }
            if (innerResult == 2) {
                continue;
            }
            missing = o.addAndGet(-missing);
            if (missing == 0) {
                break;
            }
        }
    }

    @SuppressWarnings("unchecked")
    public static <T, R> boolean tryScalarXMapSubscribe(ObservableSource<T> source,
            Observer<? super R> observer,
            Function<? super T, ? extends ObservableSource<? extends R>> mapper) {
        if (source instanceof Supplier) {
            T t;
            try {
                Supplier<T> supplier = (Supplier<T>) source;
                t = supplier.get();
            } catch (Throwable ex) {
                Exceptions.throwIfFatal(ex);
                errorObserver(ex, observer);
                return true;
            }
            if (t == null) {
                completeObserver(observer);
                return true;
            }
            ObservableSource<? extends R> r;
            try {
                ObservableSource<? extends R> mapped = mapper.apply(t);
                r = Objects.requireNonNull(mapped, "The mapper returned a null ObservableSource");
            } catch (Throwable ex) {
                Exceptions.throwIfFatal(ex);
                errorObserver(ex, observer);
                return true;
            }
            subscribeScalarMapped(r, observer);
            return true;
        }
        return false;
    }

    @SuppressWarnings("unchecked")
    public static <R> void subscribeScalarMapped(ObservableSource<? extends R> r, Observer<? super R> observer) {
        if (r instanceof Supplier) {
            R u;
            try {
                u = ((Supplier<R>) r).get();
            } catch (Throwable ex) {
                Exceptions.throwIfFatal(ex);
                errorObserver(ex, observer);
                return;
            }
            if (u == null) {
                completeObserver(observer);
                return;
            }
            ObservableScalarXMap.ScalarDisposable<R> sd = new ObservableScalarXMap.ScalarDisposable<>(observer, u);
            observer.onSubscribe(sd);
            sd.run();
        } else {
            r.subscribe(observer);
        }
    }

    public static void completeObserver(Observer<?> observer) {
        observer.onSubscribe(EmptyDisposable.INSTANCE);
        observer.onComplete();
    }

    public static void errorObserver(Throwable e, Observer<?> observer) {
        observer.onSubscribe(EmptyDisposable.INSTANCE);
        observer.onError(e);
    }

    public static <T, U> boolean dispatchMapOnNext(boolean done, int sourceMode, Observer<? super U> downstream,
            Function<? super T, ? extends U> mapper, T t, MapFailHandler handler) {
        if (done) {
            return true;
        }
        if (sourceMode != QueueDisposable.NONE) {
            downstream.onNext(null);
            return true;
        }
        U v;
        try {
            v = Objects.requireNonNull(mapper.apply(t), "The mapper function returned a null value.");
        } catch (Throwable ex) {
            handler.failMapped(ex);
            return true;
        }
        downstream.onNext(v);
        return true;
    }

    @SuppressWarnings("unchecked")
    public static <T, U> U pollMapped(SimpleQueue<T> qd, Function<? super T, ? extends U> mapper) throws Throwable {
        T t = qd.poll();
        return t != null ? Objects.requireNonNull(mapper.apply(t), "The mapper function returned a null value.") : null;
    }

    public static <T, R> void subscribeScanSeed(ObservableSource<T> source, Observer<? super R> t,
            Supplier<R> seedSupplier, BiFunction<R, ? super T, R> accumulator) {
        R r;
        try {
            r = Objects.requireNonNull(seedSupplier.get(), "The seed supplied is null");
        } catch (Throwable e) {
            Exceptions.throwIfFatal(e);
            errorObserver(e, t);
            return;
        }
        source.subscribe(new ObservableScanSeed.ScanSeedObserver<>(t, accumulator, r));
    }

    public static <T, R> void scanSeedOnSubscribe(ObservableScanSeed.ScanSeedObserver<T, R> observer, Disposable d) {
        Disposable current = observer.upstream;
        if (!DisposableHelper.validate(current, d)) {
            return;
        }
        observer.upstream = d;
        Observer<? super R> downstream = observer.downstream;
        downstream.onSubscribe(observer);
        R seed = observer.value;
        downstream.onNext(seed);
    }

    public static <T, R> void scanSeedOnNext(ObservableScanSeed.ScanSeedObserver<T, R> observer, T t) {
        if (observer.done) {
            return;
        }
        R previous = observer.value;
        R next;
        try {
            next = Objects.requireNonNull(observer.accumulator.apply(previous, t), "The accumulator returned a null value");
        } catch (Throwable e) {
            Exceptions.throwIfFatal(e);
            observer.upstream.dispose();
            observer.onError(e);
            return;
        }
        observer.value = next;
        observer.downstream.onNext(next);
    }

    public static <T, R> void scanSeedOnError(ObservableScanSeed.ScanSeedObserver<T, R> observer, Throwable t) {
        if (observer.done) {
            RxJavaPlugins.onError(t);
            return;
        }
        observer.done = true;
        observer.downstream.onError(t);
    }

    public static <T, R> void scanSeedOnComplete(ObservableScanSeed.ScanSeedObserver<T, R> observer) {
        if (observer.done) {
            return;
        }
        observer.done = true;
        observer.downstream.onComplete();
    }

    public static <T, R> void scanSeedDispose(ObservableScanSeed.ScanSeedObserver<T, R> observer) {
        observer.upstream.dispose();
    }

    public static <T, R> boolean scanSeedIsDisposed(ObservableScanSeed.ScanSeedObserver<T, R> observer) {
        return observer.upstream.isDisposed();
    }

    public static <T> void serializeOnNext(Observer<? super T> observer, T value,
            AtomicInteger wip, AtomicThrowable errors) {
        if (wip.get() != 0) {
            return;
        }
        if (!wip.compareAndSet(0, 1)) {
            return;
        }
        observer.onNext(value);
        if (wip.decrementAndGet() != 0) {
            errors.tryTerminateConsumer(observer);
        }
    }

    public static void serializeOnError(Observer<?> observer, Throwable ex,
            AtomicInteger wip, AtomicThrowable errors) {
        if (!errors.tryAddThrowableOrReport(ex)) {
            return;
        }
        if (wip.getAndIncrement() == 0) {
            errors.tryTerminateConsumer(observer);
        }
    }

    public static void serializeOnComplete(Observer<?> observer, AtomicInteger wip, AtomicThrowable errors) {
        if (wip.getAndIncrement() != 0) {
            return;
        }
        errors.tryTerminateConsumer(observer);
    }


    static <T, U> void drainConcatMap(ObservableConcatMap.SourceObserver<T, U> o) {
        if (o.getAndIncrement() != 0) {
            return;
        }
        for (;;) {
            if (o.disposed) {
                o.queue.clear();
                return;
            }
            if (!o.active) {
                boolean d = o.done;
                T t;
                try {
                    t = o.queue.poll();
                } catch (Throwable ex) {
                    Exceptions.throwIfFatal(ex);
                    o.dispose();
                    o.queue.clear();
                    o.downstream.onError(ex);
                    return;
                }
                boolean empty = t == null;
                if (d && empty) {
                    o.disposed = true;
                    o.downstream.onComplete();
                    return;
                }
                if (!empty) {
                    ObservableSource<? extends U> src;
                    try {
                        src = Objects.requireNonNull(o.mapper.apply(t), "The mapper returned a null ObservableSource");
                    } catch (Throwable ex) {
                        Exceptions.throwIfFatal(ex);
                        o.dispose();
                        o.queue.clear();
                        o.downstream.onError(ex);
                        return;
                    }
                    o.active = true;
                    src.subscribe(o.inner);
                }
            }
            if (o.decrementAndGet() == 0) {
                break;
            }
        }
    }

    static <T, U> void subscribeConcatMapMain(ObservableConcatMap.SourceObserver<T, U> o, Disposable d) {
        if (!DisposableHelper.validate(o.upstream, d)) {
            return;
        }
        o.upstream = d;
        if (!(d instanceof QueueDisposable)) {
            o.queue = new SpscLinkedArrayQueue<>(o.bufferSize);
            o.downstream.onSubscribe(o);
            return;
        }
        @SuppressWarnings("unchecked")
        QueueDisposable<T> qd = (QueueDisposable<T>) d;
        int m = qd.requestFusion(QueueDisposable.ANY);
        if (m == QueueDisposable.SYNC) {
            o.fusionMode = m;
            o.queue = qd;
            o.done = true;
            o.downstream.onSubscribe(o);
            drainConcatMap(o);
            return;
        }
        if (m == QueueDisposable.ASYNC) {
            o.fusionMode = m;
            o.queue = qd;
            o.downstream.onSubscribe(o);
            return;
        }
        o.queue = new SpscLinkedArrayQueue<>(o.bufferSize);
        o.downstream.onSubscribe(o);
    }

    static <T, U> void onNextConcatMap(ObservableConcatMap.SourceObserver<T, U> o, T t) {
        if (o.done) {
            return;
        }
        if (o.fusionMode == QueueDisposable.NONE) {
            o.queue.offer(t);
        }
        drainConcatMap(o);
    }

    static <T, U> void onErrorConcatMap(ObservableConcatMap.SourceObserver<T, U> o, Throwable t) {
        if (o.done) {
            RxJavaPlugins.onError(t);
            return;
        }
        o.done = true;
        o.dispose();
        o.downstream.onError(t);
    }

    static <T, U> void onCompleteConcatMap(ObservableConcatMap.SourceObserver<T, U> o) {
        if (o.done) {
            return;
        }
        o.done = true;
        drainConcatMap(o);
    }

    static <T, U> void disposeConcatMap(ObservableConcatMap.SourceObserver<T, U> o) {
        o.disposed = true;
        o.inner.dispose();
        o.upstream.dispose();
        if (o.getAndIncrement() == 0) {
            o.queue.clear();
        }
    }

    @SuppressWarnings("unchecked")
    static <T, R> void drainConcatMapDelayError(ObservableConcatMap.ConcatMapDelayErrorObserver<T, R> o) {
        if (o.getAndIncrement() != 0) {
            return;
        }
        Observer<? super R> downstream = o.downstream;
        SimpleQueue<T> queue = o.queue;
        AtomicThrowable errors = o.errors;
        for (;;) {
            if (!o.active) {
                if (o.cancelled) {
                    queue.clear();
                    return;
                }
                if (!o.tillTheEnd) {
                    Throwable ex = errors.get();
                    if (ex != null) {
                        queue.clear();
                        o.cancelled = true;
                        errors.tryTerminateConsumer(downstream);
                        return;
                    }
