    @Test
    public void innerIgnoresCancelAndErrors() throws Throwable {
        TestHelper.withErrorTracking(errors -> {
            PublishSubject<Integer> ps = PublishSubject.create();

            TestObserver<Object> to = ps
            .switchMap(v -> {
                if (v == 1) {
