        Observable.just(1)
        .hide()
        .switchMap(v -> Observable.just(1)
                .doOnSubscribe(d -> to.dispose())
                .scan(1, (a, b) -> a)
        )
        .subscribe(to);

        to.assertEmpty();
    }
